// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IStandardToken {
    function owner() external view returns (address);
    function MINT_FORBIDDEN() external view returns (bool);
    function forbidMint() external;
    function setFees(uint256 _liquidity, uint256 _holders, uint256 _burn, uint256 _denominator) external;
    function fees() external view returns (uint256 liquidity, uint256 holders, uint256 burn, uint256 total, uint256 _denominator);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xEa01D8D9EaCCa9996Db6Bb3377c1Fe64308e7328;
    address attacker = address(this);
    address owner;
    IStandardToken target;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        target = IStandardToken(TARGET);
        owner = target.owner();
        vm.label(owner, "Contract Owner");
        vm.label(TARGET, "Target Contract");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // Record initial state
        bool initialMintForbidden = target.MINT_FORBIDDEN();
        assertEq(initialMintForbidden, false, "MINT_FORBIDDEN should be false initially");

        // Impersonate owner and call forbidMint() - NO EVENT EMITTED
        vm.startPrank(owner);
        target.forbidMint();
        vm.stopPrank();

        // Verify state changed
        bool finalMintForbidden = target.MINT_FORBIDDEN();
        assertEq(finalMintForbidden, true, "MINT_FORBIDDEN should be true after exploit");

        // The oracle verifies no event was emitted for this critical state change
        // This is the vulnerability - state changed without event emission
        assertTrue(finalMintForbidden, "Logic Exploit Failed: Value unchanged");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

